/* Lot 101: currentcolor in the reader paint, with lab(), lch(), oklab(), oklch() and color() (generated by scripts/lot101_colorgen.py; expectations from scripts/lot101_colormodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body id=b>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l101_paint_0(void) {
    prep("body { background: currentColor } #o { background: url(x.png) color-mix(in srgb, currentColor 0%, hsla(100grad 81.4% 65.3% / 2)) } #i { color: color-mix(in srgb, lab(2 92.3504 -70), oklab(0.7686	77.43%	-0.3612)); background-color: lab(13.2863  -69.0644  -101.77/ 120%) }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#000000\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#8646a0;background-color:#001d1d\"", style_of("i"));
    prep("body { background-color: oklab(2% 39.4% 0.0483) } #o { color: currentcolor }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#000000\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    prep("body { color: hwb(-320grad 100% 88%/90%); background: color-mix(in srgb, Lch(81.49 187 239.2deg), saddlebrown) } #o { background-color: currentcolor }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#888888e6\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#888888e6\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
    prep("body { background: no-repeat currentcolor } #o { color: hsl(388.68grad 36% 50% / 150%) } #i { color: #2ffccd }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#000000;background-repeat:no-repeat\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#ad5261\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#2ffccd\"", style_of("i"));
    prep("body { color: white; background-color: color-mix(in srgb, rgb(68 220 62 / 0.07), CURRENTCOLOR 79.7264%) } #i { color: rebeccapurple; background-color: color(p3 0 0.678 0) }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#ffffff;background-color:#fcfefccf\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#663399\"", style_of("i"));
    prep("body { color: color-mix(in srgb, currentColor, color(display-p3  0  0.5  0.88)) } #o { color: color-mix(in srgb, rgb(239.23, 7, 93%), currentColor 50%); background-color: currentColor } #i { background: url(x.png) color( xyz +0.5 0.4266 -0.116/ 73%) }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#004170\"", style_of("b"));
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#7824af;background-color:#7824af\"", style_of("o"));
    TEST_ASSERT_EQUAL_STRING("", style_of("i"));
}

